  // 动态渲染 Koboyo 手绘图标，支持传入 Tailwind 类名
  koboyo(name, classes = "w-4 h-4 inline-block shrink-0") {
    const raw = this.koboyoRaw[name];
    if (!raw) return "";
    return raw.replace("<svg ", `<svg class="${classes}" `);
  },

  // 便捷属性
  get koboyoEar() { return this.koboyo("ear"); },
  get koboyoMic() { return this.koboyo("mic"); },
  get koboyoBrain() { return this.koboyo("brain"); },
  get koboyoBot() { return this.koboyo("bot"); },
  get koboyoSparkles() { return this.koboyo("sparkles"); },
  get koboyoShield() { return this.koboyo("shield"); },
  get koboyoDetective() { return this.koboyo("detective"); },
  get koboyoCoffee() { return this.koboyo("coffee"); },
  get koboyoSmile() { return this.koboyo("smile"); },
  get koboyoRocket() { return this.koboyo("rocket"); },
  get koboyoNotebook() { return this.koboyo("notebook"); },
  get koboyoHeadset() { return this.koboyo("headset"); },
  get koboyoSearch() { return this.koboyo("search"); },

